// A shared horizontal time scale; every connector represents one documented mapping.
const timelineSection=document.querySelector('#timeline');
const viewTabs=document.createElement('div');viewTabs.className='view-tabs';viewTabs.setAttribute('role','tablist');viewTabs.setAttribute('aria-label','역사 보기 방식');
viewTabs.innerHTML='<button id="tab-history" role="tab" aria-controls="timeline" aria-selected="true">세로 역사 연표</button><button id="tab-map" role="tab" aria-controls="connections" aria-selected="false">논문 ↔ 릴리즈 연결 <span>가로 시간축</span></button>';
timelineSection.before(viewTabs);
const mapPanel=document.createElement('section');mapPanel.id='connections';mapPanel.setAttribute('role','tabpanel');mapPanel.setAttribute('aria-labelledby','tab-map');mapPanel.hidden=true;
mapPanel.innerHTML=`<p class="eyebrow">PAPER → API / CONNECTION MAP</p><h2>어떤 논문이, 어떤 릴리즈로 이어졌나</h2><p class="map-intro">한 행이 하나의 논문입니다. <b>◆ 논문 발표</b>에서 <b>● MATLAB 릴리즈</b>로 이어지는 선을 따라가세요.<br>점이나 연결선을 누르면 해당 함수와 대응 근거를 아래에서 확인할 수 있습니다.</p><div class="map-controls"><label>분야 <select id="map-topic" aria-label="연결 지도 분야"><option value="all">전체</option><option value="LiDAR">LiDAR</option><option value="Vision">Vision</option><option value="Backend">최적화 · 융합</option></select></label><label>시간 범위 <select id="map-range" aria-label="연결 지도 시간 범위"><option value="recent">2008–2026 확대</option><option value="all">1981–2026 전체</option></select></label><label>연구 <select id="map-paper" aria-label="연결 지도 연구"><option value="all">전체 논문</option>${PAPERS.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></label><label>관계 <select id="map-relation" aria-label="연결 지도 관계"><option value="all">모든 관계</option><option value="direct">공식 인용만</option></select></label><button id="map-reset">초기화</button></div><div class="map-legend"><span>◆ 논문 발표</span><span class="direct">━ 공식 문서 인용</span><span class="continuation">━ 후속 API 변화</span><span class="background">┄ 배경 읽기</span></div><p class="map-note">가로 위치는 시간에 비례합니다. a/b는 같은 해의 전반/후반을 구분하는 위치이며 정확한 출시일이 아닙니다. 축 이전 논문은 왼쪽 경계에 ◀로 표시합니다.</p><p id="map-count" role="status" aria-live="polite"></p><div class="map-scroll" tabindex="0" aria-label="논문과 릴리즈 연결 그래프. 좁은 화면에서는 가로로 스크롤할 수 있습니다."><div id="map-graph"></div></div><div id="map-detail" tabindex="-1" aria-live="polite"></div>`;
timelineSection.after(mapPanel);timelineSection.setAttribute('role','tabpanel');timelineSection.setAttribute('aria-labelledby','tab-history');
let selectedEdge=null;
const color={direct:'#137c72',continuation:'#66859a',background:'#b2833d'};
function showView(which){const isMap=which==='map';mapPanel.hidden=!isMap;timelineSection.hidden=isMap;document.querySelector('#tab-map').setAttribute('aria-selected',String(isMap));document.querySelector('#tab-history').setAttribute('aria-selected',String(!isMap));document.querySelector('#tab-map').tabIndex=isMap?0:-1;document.querySelector('#tab-history').tabIndex=isMap?-1:0;history.replaceState(null,'',isMap?'#connections':'#timeline');viewTabs.scrollIntoView({behavior:'smooth',block:'start'});}
document.querySelector('#tab-map').onclick=()=>showView('map');document.querySelector('#tab-history').onclick=()=>showView('history');
viewTabs.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?'history':e.key==='End'?'map':mapPanel.hidden?'map':'history';showView(next);document.querySelector(next==='map'?'#tab-map':'#tab-history').focus();}});
document.querySelectorAll('a[href="#timeline"]').forEach(a=>a.addEventListener('click',()=>showView('history')));
function selectEdge(p,index,focus=false){selectedEdge=p.id+'-'+index;const e=p.edges[index];const r=HISTORY.find(r=>r.release===e[0]&&r.apis.includes(e[1]));document.querySelectorAll('.map-edge').forEach(g=>g.classList.toggle('selected',g.dataset.edge===selectedEdge));document.querySelector('#map-detail').innerHTML=`<div class="detail-top"><span>${RELATIONS[e[2]]}</span><b>${p.year} 논문 → ${e[0]}</b></div><h3>${p.name} → <code>${e[1]}</code></h3><p>${e[3]}</p><p class="map-bibliography">${p.title}<br>${p.authors} · ${p.venue}</p><div class="detail-links"><a href="${p.url}" target="_blank" rel="noopener">논문 원문 ↗</a><a href="${p.evidence}" target="_blank" rel="noopener">논문 대응 근거 ↗</a><a href="${r.url}" target="_blank" rel="noopener">릴리즈 근거 ↗</a><button id="map-to-history">세로 연표에서 이 계보 보기 →</button></div>`;document.querySelector('#map-to-history').onclick=()=>{showView('history');selectLineage(p.id);};if(focus)document.querySelector('#map-detail').scrollIntoView({behavior:'smooth',block:'nearest'});}
function drawMap(){const topic=document.querySelector('#map-topic').value,paper=document.querySelector('#map-paper').value,relation=document.querySelector('#map-relation').value;const start=document.querySelector('#map-range').value==='all'?1980:2008,end=2027;
const rows=PAPERS.filter(p=>(topic==='all'||p.tags.includes(topic))&&(paper==='all'||p.id===paper)).map(p=>({p,edges:p.edges.map((e,i)=>({e,i})).filter(({e})=>relation==='all'||e[2]==='direct')})).filter(r=>r.edges.length).sort((a,b)=>b.p.year-a.p.year);
const x=y=>270+(Math.max(start,y)-start)/(end-start)*910;let top=66;
let svg='';let first=null;const positions=[];
for(const {p,edges} of rows){const height=Math.max(100,edges.length*64+24),cy=top+height/2;positions.push({top,height});const px=x(p.year);svg+=`<g class="map-row"><rect x="0" y="${top}" width="1240" height="${height}" fill="${positions.length%2?'#f5f8fa':'#ffffff'}"/><text x="18" y="${cy-6}" class="row-title">${p.name}</text><text x="18" y="${cy+15}" class="row-sub">${p.year} · ${p.tags.join(' / ')}</text><line x1="250" y1="${top+height}" x2="1210" y2="${top+height}" stroke="#dfe7ec"/>`;
edges.forEach(({e,i},j)=>{const tx=x(Number(e[0].slice(1,5))+(e[0].endsWith('a')?.25:.75)),ty=top+28+j*64;const key=p.id+'-'+i;if(!first)first={p,i};const dash=e[2]==='background'?'stroke-dasharray="5 5"':'';const d=`M ${px} ${cy} C ${px+35} ${cy},${tx-40} ${ty},${tx} ${ty}`;svg+=`<g class="map-edge" data-edge="${key}" role="button" tabindex="0" aria-label="${p.name} ${p.year} → ${e[0]} ${e[1]} · ${RELATIONS[e[2]]}"><title>${p.name} (${p.year}) → ${e[0]} · ${e[1]} · ${RELATIONS[e[2]]}</title><path d="${d}" stroke="transparent" stroke-width="16" fill="none"/><path class="visible-edge" d="${d}" stroke="${color[e[2]]}" stroke-width="2" ${dash} fill="none"/><circle cx="${tx}" cy="${ty}" r="5" fill="${color[e[2]]}"/><text x="${tx-9}" y="${ty-9}" text-anchor="end" class="edge-release">${e[0]}</text><text x="${tx-9}" y="${ty+17}" text-anchor="end" class="edge-api">${e[1]}</text></g>`;});
svg+=`<path d="M ${px} ${cy-7} L ${px+7} ${cy} L ${px} ${cy+7} L ${px-7} ${cy} Z" fill="#b67e44"/><text x="${px-12}" y="${cy+4}" text-anchor="end" class="paper-year">${p.year<start?'◀ ':''}${p.year}</text></g>`;top+=height;}
let grid='';const step=start===1980?5:2;for(let y=start;y<=2026;y+=step){grid+=`<line x1="${x(y)}" x2="${x(y)}" y1="55" y2="${top}" stroke="#cbd9e1" stroke-dasharray="2 5"/><text x="${x(y)}" y="36" text-anchor="middle" class="axis-year">${y}</text>`;}
const axis=`<rect width="1240" height="55" fill="#eaf0f4"/><text x="18" y="34" class="axis-title">논문 / 연구</text><text x="1207" y="18" text-anchor="end" class="axis-sub">시간 →</text>`;
document.querySelector('#map-graph').innerHTML=rows.length?`<svg viewBox="0 0 1240 ${top+10}" xmlns="http://www.w3.org/2000/svg" aria-label="가로 시간축의 논문-릴리즈 대응 지도">${svg}${axis}<g pointer-events="none">${grid}</g></svg>`:'<p class="empty">선택한 조건에 대응하는 논문이 없습니다.</p>';
document.querySelector('#map-count').textContent=`${rows.length}편 · ${rows.reduce((n,r)=>n+r.edges.length,0)}개 연결 · ${start===1980?'전체 시간축':'2008년 이전은 축 경계에 표시'}`;
document.querySelectorAll('.map-edge').forEach(g=>{const [id,index]=g.dataset.edge.split(/-(?=\d+$)/);const p=PAPERS.find(p=>p.id===id);const action=()=>selectEdge(p,Number(index),true);g.onclick=action;g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();action();}};});
if(first)selectEdge(first.p,first.i);else document.querySelector('#map-detail').innerHTML='';}
['map-topic','map-range','map-paper','map-relation'].forEach(id=>document.querySelector('#'+id).addEventListener('change',drawMap));document.querySelector('#map-reset').onclick=()=>{document.querySelector('#map-topic').value='all';document.querySelector('#map-range').value='recent';document.querySelector('#map-paper').value='all';document.querySelector('#map-relation').value='all';drawMap();};drawMap();if(location.hash==='#connections')showView('map');
